		if eligible != len(sorted) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, sorted, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(sorted)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit"
			("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
			SELECT $1, t.id, $2, $3, $4, 'submitted', 'approved' FROM unnest($5::text[]) AS t(id)`,
			u.Tenant, u.User, operation, key, sorted)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(sorted)) {
			return protocol.Result{}, false, errors.New("audit insert count mismatch")
		}
		if err = tx.Commit(ctx); err != nil {
			// Commit outcome may be unknown; client retries with the same key to read it.
			return protocol.Result{}, false, err
		}
		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

// replay returns the stored result for an already-completed scope, or 409 if the
// same key was used for a different target set. It performs no writes.
func replay(ctx context.Context, tx pgx.Tx, u app.Identity, key, hash string) (protocol.Result, bool, error) {
	var storedHash string
	var stored []byte
	err := tx.QueryRow(ctx, `SELECT "requestHash", response::text FROM "ActionRequest"
		WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
		u.Tenant, u.User, operation, key).Scan(&storedHash, &stored)
	if err != nil {
		return protocol.Result{}, false, err
	}
	if storedHash != hash {
		return protocol.Result{}, false, &protocol.Rejection{Status: 409}
	}
	var result protocol.Result
	if err = json.Unmarshal(stored, &result); err != nil {
		return protocol.Result{}, false, err
	}
	if result.ApprovedIDs == nil {
		result.ApprovedIDs = []string{}
	}
	return result, true, nil
}

